CREATE TABLE IF NOT EXISTS app_meta(name VARCHAR(200) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS accounts(id INT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(254) NOT NULL UNIQUE,note VARCHAR(1000) NOT NULL DEFAULT '',created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS families(id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(200) NOT NULL,manager_id INT NOT NULL UNIQUE,created_at VARCHAR(30) NOT NULL,service VARCHAR(20) NOT NULL DEFAULT 'youtube',note VARCHAR(1000) NOT NULL DEFAULT '',FOREIGN KEY(manager_id) REFERENCES accounts(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS members(id INT PRIMARY KEY AUTO_INCREMENT,family_id INT NOT NULL,email VARCHAR(254) NOT NULL,customer_name VARCHAR(200) NOT NULL DEFAULT '',contact VARCHAR(1000) NOT NULL DEFAULT '',joined_at VARCHAR(10) NOT NULL DEFAULT '',expires_at VARCHAR(10) NOT NULL DEFAULT '',payment_status VARCHAR(20) NOT NULL DEFAULT 'unpaid',amount INT NOT NULL DEFAULT 0,plan_months INT NOT NULL DEFAULT 0,note VARCHAR(1000) NOT NULL DEFAULT '',renewal_status VARCHAR(30) NOT NULL DEFAULT 'not_contacted',renewal_amount INT NOT NULL DEFAULT 0,renewal_paid_at VARCHAR(10) NOT NULL DEFAULT '',renewal_note VARCHAR(1000) NOT NULL DEFAULT '',renewal_revision INT NOT NULL DEFAULT 0,declined_at VARCHAR(30) NOT NULL DEFAULT '',membership_status VARCHAR(20) NOT NULL DEFAULT 'unknown',UNIQUE(family_id,email),FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS logs(id INT PRIMARY KEY AUTO_INCREMENT,message TEXT NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS archived_customers(id INT PRIMARY KEY AUTO_INCREMENT,original_member_id INT NOT NULL,email VARCHAR(254) NOT NULL,customer_name VARCHAR(200) NOT NULL,family_name VARCHAR(200) NOT NULL,manager_email VARCHAR(254) NOT NULL,snapshot LONGTEXT NOT NULL,archived_at VARCHAR(30) NOT NULL,reason VARCHAR(255) NOT NULL,restored_at VARCHAR(30) NULL,restored_by VARCHAR(200) NULL,restored_member_id INT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS renewal_history(id INT PRIMARY KEY AUTO_INCREMENT,member_id INT NULL,email VARCHAR(254) NOT NULL,customer_name VARCHAR(200) NOT NULL,family_name VARCHAR(200) NOT NULL,old_expires_at VARCHAR(10) NOT NULL,new_expires_at VARCHAR(10) NOT NULL,plan_months INT NOT NULL,amount INT NOT NULL,paid_at VARCHAR(10) NOT NULL,note VARCHAR(1000) NOT NULL,created_at VARCHAR(30) NOT NULL,created_by VARCHAR(200) NOT NULL,old_purchase_at VARCHAR(10) NOT NULL DEFAULT '',new_purchase_at VARCHAR(10) NOT NULL DEFAULT '',archive_id INT NULL,FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS other_purchases(id INT PRIMARY KEY AUTO_INCREMENT,product VARCHAR(100) NOT NULL,customer_name VARCHAR(200) NOT NULL,email VARCHAR(254) NOT NULL,contact VARCHAR(1000) NOT NULL,joined_at VARCHAR(10) NOT NULL,expires_at VARCHAR(10) NOT NULL,payment_status VARCHAR(20) NOT NULL,amount INT NOT NULL,note VARCHAR(1000) NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
